questionvariables.text:
/* Design: least waste (waste-reduction PCI). Source: original. The least waste is unique and at least 2 below the next; the best plan uses both items.
   fw: the plan with the fewest items when it is not the best (entries 3, 6, 7), else [-1, -1] so its node never fires. */
/* lincan(q): canonical form of a linear inequality in x and y: [strict?, [a, b, c]] meaning a*x + b*y + c (< or <=) 0 */
lincan(q) := block([r, d, s], r: op(q), d: expand(lhs(q) - rhs(q)),
    if r = ">" or r = ">=" then d: -d,
    s: is(r = "<" or r = ">"),
    [s, map(lambda([t], float(t)), [coeff(d, x), coeff(d, y), subst([x = 0, y = 0], d)])]);
lpar(u, v) := is(abs(u[1]*v[2] - u[2]*v[1]) + abs(u[1]*v[3] - u[3]*v[1]) + abs(u[2]*v[3] - u[3]*v[2]) < 1/10^9 * (abs(u[1]) + abs(u[2]) + abs(u[3])) * (abs(v[1]) + abs(v[2]) + abs(v[3])));
ldot(u, v) := u[1]*v[1] + u[2]*v[2] + u[3]*v[3];
/* lcls(L, T): "same" region; "dir" same boundary, other side, same strictness; "strict" same side, other strictness; "both"; "other" */
lcls(L, T) := block([l: lincan(L), t: lincan(T)],
    if not lpar(l[2], t[2]) then "other"
    elseif ldot(l[2], t[2]) > 0 then (if l[1] = t[1] then "same" else "strict")
    elseif l[1] = t[1] then "dir" else "both");
/* the validator: an inequality in x and y, linear */
validate_ineq(ex) := block([e: ev(ex, simp), d],
    if atom(e) or not member(op(e), ["<", "<=", ">", ">="]) then
        "Type an inequality using <, <=, > or >=, for example 2*x+3*y<=60. An equation with = is not an inequality."
    elseif listofvars(e) = [] or not every(lambda([v], member(v, [x, y])), listofvars(e)) then "Use only the letters x and y."
    else (d: ev(expand(lhs(e) - rhs(e)), simp),
          if not ev(polynomialp(d, [x, y]), simp) then
              "This inequality should be linear: only numbers times x and y, added or subtracted."
          elseif ev(hipow(d, x), simp) > 1 or ev(hipow(d, y), simp) > 1 or not freeof(x, ev(coeff(d, y), simp)) then
              "This inequality should be linear: no powers or products of x and y." else ""));
/* mkineq([a, b, rel, c]): the inequality a*x + b*y rel c */
mkineq(L) := if L[3] = "<=" then L[1]*x + L[2]*y <= L[4] elseif L[3] = "<" then L[1]*x + L[2]*y < L[4]
    elseif L[3] = ">=" then L[1]*x + L[2]*y >= L[4] else L[1]*x + L[2]*y > L[4];
Q43L: [["A day school kitchen in Embu must serve at least \\(219\\) servings of lunch. A small pot of githeri gives \\(31\\) servings and a pot of rice gives \\(18\\). A pot of githeri uses \\(8\\) bundles of firewood and a pot of rice uses \\(3\\); there are \\(48\\) bundles. Let \\(x\\) be the number of pots of githeri and \\(y\\) the number of pots of rice. Food cooked beyond what is needed is wasted.",31,18,219,8,3,48,[3,7],0,[-1,-1],0,[0,13],[0,17],"servings"],
["A caterer at a wedding in Kisumu must provide at least \\(507\\) servings. A tray of pilau gives \\(60\\) servings and a tray of chapati gives \\(43\\). A tray of pilau uses \\(8\\) kg of charcoal and a tray of chapati uses \\(1\\) kg; there are \\(29\\) kg of charcoal. Let \\(x\\) be the number of trays of pilau and \\(y\\) the number of trays of chapati. Food cooked beyond what is needed is wasted.",60,43,507,8,1,29,[2,9],0,[-1,-1],0,[0,12],[1,22],"servings"],
["A dairy cooperative in Nyeri must deliver at least \\(326\\) litres of milk to a school. A large churn holds \\(79\\) litres and a small churn holds \\(50\\) litres, and every churn sent is filled. Sending a large churn costs Ksh \\(900\\) and a small churn Ksh \\(100\\); the budget is Ksh \\(6800\\). Let \\(x\\) be the number of large churns and \\(y\\) the number of small churns. Milk beyond the order goes sour and is wasted.",79,50,326,9,1,68,[1,5],3,[3,2],11,[0,7],[5,24],"litres"],
["A feed store in Nakuru must supply at least \\(358\\) kg of layers mash to a farmer. A large bag holds \\(45\\) kg and a small bag holds \\(37\\) kg. Delivering a large bag costs Ksh \\(700\\) and a small bag Ksh \\(100\\); the delivery budget is Ksh \\(3700\\). Let \\(x\\) be the number of large bags and \\(y\\) the number of small bags. Mash beyond the order goes stale and is wasted.",45,37,358,7,1,37,[4,5],7,[-1,-1],7,[0,10],[2,24],"kg"],
["A water project near Garissa must bring at least \\(274\\) jerrycans of water to a village in a day. A tractor-bowser trip brings \\(44\\) jerrycans and a trip by a pickup with a water tank brings \\(28\\). A tractor-bowser trip costs Ksh \\(700\\) in fuel and a pickup trip Ksh \\(200\\); there is Ksh \\(4900\\) a day. Let \\(x\\) be the number of tractor-bowser trips and \\(y\\) the number of pickup trips. Water beyond what the village can store is wasted.",44,28,274,7,2,49,[5,2],2,[-1,-1],2,[0,10],[0,25],"jerrycans"],
["A school in Machakos must give at least \\(288\\) learners a packet of milk. A crate holds \\(59\\) packets and a box holds \\(46\\) packets. A crate costs Ksh \\(900\\) and a box Ksh \\(700\\); the budget is Ksh \\(5400\\). Let \\(x\\) be the number of crates and \\(y\\) the number of boxes. Packets beyond one a learner go off and are wasted.",59,46,288,9,7,54,[1,5],1,[5,0],7,[0,7],[0,8],"packets"],
["A church in Naivasha must serve at least \\(160\\) cups of tea after a fundraising service. An urn makes \\(27\\) cups and a flask makes \\(17\\) cups. Preparing an urn takes \\(7\\) minutes of volunteers' time and a flask \\(3\\) minutes; there are \\(37\\) minutes. Let \\(x\\) be the number of urns and \\(y\\) the number of flasks. Tea made beyond what is needed is poured away.",27,17,160,7,3,37,[1,8],3,[3,5],6,[0,10],[0,13],"cups"],
["A relief agency in Turkana must give out at least \\(379\\) kg of maize flour. A large sack holds \\(89\\) kg and a small sack holds \\(47\\) kg. Transporting a large sack costs Ksh \\(900\\) and a small sack Ksh \\(100\\); the budget is Ksh \\(4700\\). Let \\(x\\) be the number of large sacks and \\(y\\) the number of small sacks. Flour beyond what is needed spoils in the store and is wasted.",89,47,379,9,1,47,[4,1],24,[-1,-1],24,[0,9],[3,21],"kg"],
["A dairy stand at a school sports day in Nyeri must fill at least \\(301\\) cups of yoghurt. A large container fills \\(73\\) cups and a small container fills \\(45\\). A large container takes \\(8\\) units of fridge space and a small one \\(1\\) unit; there are \\(77\\) units. Let \\(x\\) be the number of large containers and \\(y\\) the number of small containers. Yoghurt beyond the cups ordered is wasted.",73,45,301,8,1,77,[3,2],8,[-1,-1],8,[0,7],[7,22],"cups"],
["A builder in Thika needs at least \\(335\\) wheelbarrows of concrete. A large mixer load gives \\(34\\) wheelbarrows and a small load gives \\(31\\). A large load uses \\(6\\) bags of cement and a small load uses \\(5\\); there are \\(77\\) bags. Let \\(x\\) be the number of large loads and \\(y\\) the number of small loads. Concrete beyond what is needed sets and is wasted.",34,31,335,6,5,77,[9,1],2,[-1,-1],2,[0,11],[0,16],"wheelbarrows of concrete"]];
ix: 1+rand(10);
E: Q43L[ix];
ga: E[2]; gb: E[3]; NN: E[4]; uc: E[5]; ud: E[6]; RR: E[7]; bst: E[8]; W: E[9]; fw: E[10]; Wfew: E[11]; pw: E[12]; ol: E[13]; un: E[14];
ta1: ga*x+gb*y>=NN; sw1: gb*x+ga*y>=NN; dr1: ga*x+gb*y<=NN;
Wof(u, w) := ga*u + gb*w - NN;
wpw: Wof(pw[1], pw[2]);
validate_int(ex) := if integerp(ev(ex, simp)) then "" else "Type whole numbers.";
